\textbf{Câu 5 (3,5 điểm).}[[br]]a) Mỗi biểu tượng ứng với $10$ học sinh.\hfill \textit{(0,25đ)}[[br]]{\small\renewcommand\arraystretch{1.2}\begin{tabular}{|l|c|c|c|c|}\hline \textbf{Xếp loại} & \textbf{Tốt} & \textbf{Khá} & \textbf{Đạt} & \textbf{Chưa đạt} \\ \hline Số học sinh & $30$ & $60$ & $70$ & $10$ \\ \hline \end{tabular}}\hfill \textit{(0,75đ)}[[br]]b) Vẽ đúng biểu đồ cột, đủ tên biểu đồ, tên hai trục, đơn vị, số liệu trên mỗi cột.\hfill \textit{(1,0đ)}[[br]]\adjustbox{max width=0.45\linewidth}{\begin{tikzpicture}[line width=0.6pt, font=\small]
\draw[-{Stealth[length=4pt]}] (0,0) -- (6.85,0);
\draw[-{Stealth[length=4pt]}] (0,0) -- (0,3.85);
\draw (-0.06,0.00) -- (0.06,0.00);
\node[left, font=\scriptsize] at (0,0.00) {$0$};
\draw[black!22, dashed] (0,0.42) -- (6.70,0.42);
\draw (-0.06,0.42) -- (0.06,0.42);
\node[left, font=\scriptsize] at (0,0.42) {$10$};
\draw[black!22, dashed] (0,0.85) -- (6.70,0.85);
\draw (-0.06,0.85) -- (0.06,0.85);
\node[left, font=\scriptsize] at (0,0.85) {$20$};
\draw[black!22, dashed] (0,1.27) -- (6.70,1.27);
\draw (-0.06,1.27) -- (0.06,1.27);
\node[left, font=\scriptsize] at (0,1.27) {$30$};
\draw[black!22, dashed] (0,1.70) -- (6.70,1.70);
\draw (-0.06,1.70) -- (0.06,1.70);
