\draw (-0.06,2.12) -- (0.06,2.12);
\node[left, font=\scriptsize] at (0,2.12) {$50$};
\draw[black!22, dashed] (0,2.55) -- (6.70,2.55);
\draw (-0.06,2.55) -- (0.06,2.55);
\node[left, font=\scriptsize] at (0,2.55) {$60$};
\draw[black!22, dashed] (0,2.98) -- (6.70,2.98);
\draw (-0.06,2.98) -- (0.06,2.98);
\node[left, font=\scriptsize] at (0,2.98) {$70$};
\draw[black!22, dashed] (0,3.40) -- (6.70,3.40);
\draw (-0.06,3.40) -- (0.06,3.40);
\node[left, font=\scriptsize] at (0,3.40) {$80$};
\node[above right, font=\scriptsize, align=left] at (0,3.85) {Số học sinh};
